insert into public.curriculum_nodes (id, curriculum_version_id, parent_node_id, node_type, code, title, sequence_order)
values
  ('46f71092-49a3-5f06-babe-f6bc7be90718', '1ec0a8d5-d9f2-5a5a-a3f0-2f8fed8ac7eb', null, 'QUALIFICATION', '2365-02', 'City & Guilds Level 2 Diploma in Electrical Installations (Buildings and Structures) (2365-02)', 1),
  ('546bd197-4520-57d8-9f6e-40fb5785d9ba', 'e1dacbc4-3463-5312-b45b-1642b746c9b0', null, 'QUALIFICATION', '2365-02', 'City & Guilds Level 2 Diploma in Electrical Installations (Buildings and Structures) (2365-02)', 1),
  ('c8a407f9-0ea3-5ed0-9f89-05125caef568', '1ec0a8d5-d9f2-5a5a-a3f0-2f8fed8ac7eb', '46f71092-49a3-5f06-babe-f6bc7be90718', 'UNIT', '202', 'Principles of Electrical Science', 2),
  ('4fc5a3cb-a3f0-5378-a97f-aae3e0ec2574', '1ec0a8d5-d9f2-5a5a-a3f0-2f8fed8ac7eb', 'c8a407f9-0ea3-5ed0-9f89-05125caef568', 'LEARNING_OUTCOME', '202-LO1', 'Understand mathematical principles which are appropriate to electrical installation, maintenance and design work', 1),
  ('49e8491b-737b-5eae-a2fa-11a5e4316306', '1ec0a8d5-d9f2-5a5a-a3f0-2f8fed8ac7eb', '4fc5a3cb-a3f0-5378-a97f-aae3e0ec2574', 'ASSESSMENT_CRITERION', '202-LO1-AC1.1', 'Identify and apply appropriate mathematical principles which are relevant to electrical work tasks', 1),
  ('e2d24bd4-0562-5b72-ba6a-e6d9c33ac01b', '1ec0a8d5-d9f2-5a5a-a3f0-2f8fed8ac7eb', 'c8a407f9-0ea3-5ed0-9f89-05125caef568', 'LEARNING_OUTCOME', '202-LO2', 'Understand standard units of measurement used in electrical installation, maintenance and design work', 2),
  ('ace1ea31-18bb-5de3-9ee9-ccc87287df47', '1ec0a8d5-d9f2-5a5a-a3f0-2f8fed8ac7eb', 'e2d24bd4-0562-5b72-ba6a-e6d9c33ac01b', 'ASSESSMENT_CRITERION', '202-LO2-AC2.1', 'Identify and use internationally recognised base and derived (SI) units of measurement', 1),
  ('ba385dba-2b2d-501f-98c9-67a76a6f6e4d', '1ec0a8d5-d9f2-5a5a-a3f0-2f8fed8ac7eb', 'e2d24bd4-0562-5b72-ba6a-e6d9c33ac01b', 'ASSESSMENT_CRITERION', '202-LO2-AC2.2', 'Identify and determine values of base and derived SI units which apply specifically to electrical quantities', 2),
  ('b3ef9e29-b0de-5f05-91fc-59fd818ca955', '1ec0a8d5-d9f2-5a5a-a3f0-2f8fed8ac7eb', 'e2d24bd4-0562-5b72-ba6a-e6d9c33ac01b', 'ASSESSMENT_CRITERION', '202-LO2-AC2.3', 'Identify appropriate electrical instruments for the measurement of different electrical quantities', 3),
