insert into public.assertion_versions (id, assertion_id, version, statement, status)
values
  ('f78d2be9-1018-5162-9667-10cc67e9a1c8', '8000f875-06a2-51cb-8f71-1fee72e377d1', 1, 'Multiplication and division are inverse operations: dividing by a non-zero number undoes multiplying by that number, and vice versa.', 'APPROVED'),
  ('1ba986a4-9988-5e91-9895-9254b37f6d00', 'a8a021f7-8920-54ed-96e9-5cdf61cf72c8', 1, 'Addition and subtraction are inverse operations: subtracting a number undoes adding that number, and vice versa.', 'APPROVED'),
  ('9afb28fe-eed7-5c42-bbf2-2fae6a9ca845', '5240cae0-1e46-5cc8-a692-97b42d62802a', 1, 'In an equation, multiplying or dividing both sides by the same non-zero value preserves the equality between the two sides.', 'APPROVED'),
  ('aedec8c3-a7d1-59f8-bec0-d5002dfd3796', '4234e488-3bbd-5dda-8c78-563b815341d5', 1, 'In an equation, adding or subtracting the same value from both sides preserves the equality between the two sides.', 'APPROVED'),
  ('471713c9-55b8-5762-bb92-197ba98baeae', 'b8928ddd-95ca-57df-8401-93471c0367e9', 1, 'Given a relationship of the form a = b times c, rearrange it algebraically to make b or c the subject.', 'APPROVED'),
  ('c5c45c57-19d3-576a-9054-5fe940758777', '6b54c422-4342-51be-82c6-bf51400ebab4', 1, 'Given a relationship of the form a = b + c, rearrange it algebraically to make b or c the subject.', 'APPROVED'),
  ('3d540b95-d671-5267-be8f-b4abbeb266de', '55719997-3fb9-5bd3-a635-bc7f54fc50a8', 1, 'Substitute known numerical values into a formula to calculate the value of the remaining unknown quantity.', 'APPROVED'),
  ('09054f4e-bf67-553e-a37a-ecae84b8fb5b', '9b09b0d8-b4c1-5da8-afaa-f0d9a5b85497', 1, 'The reciprocal of a non-zero number is 1 divided by that number.', 'APPROVED'),
  ('c7ac0ed5-6959-5a53-83f6-cc1b2771240e', '9d1f4f38-5639-50f7-a4c8-17cf08726ca7', 1, 'Apply the four arithmetic operations (addition, subtraction, multiplication, division) to fractions, including proper and improper fractions.', 'APPROVED'),
  ('fcdee42a-e36c-52c6-b806-391be56886b0', '1f8a6fa0-6265-5db1-9d1e-df9cc9e1dc30', 1, 'When a governed relationship has the form 1/T = 1/a + 1/b + ... , the total T is found by summing the reciprocals of each individual contribution (1/a, 1/b, ...) to give 1/T.', 'APPROVED'),
  ('397f462f-4e01-58a1-b126-786594914462', '24f2f4be-018b-5c8b-a7a1-634dac3a9a68', 1, 'Once the reciprocal of a total quantity has been calculated, take its reciprocal again to find the value of the total quantity itself.', 'APPROVED'),
  ('d07e37ab-9036-599e-aaa9-fdab3d1f101b', '3b190e22-d627-52f8-a1eb-1faef206d10f', 1, 'A percentage expresses a quantity as a number of parts per hundred, and can be used to express one quantity as a proportion of another.', 'APPROVED'),
  ('1e803b49-5984-5a6e-8d88-c675e76d638b', '0a27d075-54ec-5d68-b3c3-2dc898a7a3d4', 1, 'Two quantities are in direct proportion when one increases in the same ratio as the other.', 'APPROVED'),
  ('0aab679e-4462-50fd-a2ae-4ff441949805', '8f3f9ccb-7211-5096-9f8b-c4b07b5a8bf1', 1, 'Two quantities are in inverse proportion when one increases in the same ratio as the other decreases.', 'APPROVED'),
  ('e5bf7a0a-8921-500b-b202-2915fb03114f', '79eb7c81-2853-5008-86f8-f40b31bc025e', 1, 'An SI prefix (such as milli-, kilo- or mega-) represents a fixed power-of-ten scale factor applied to a base or derived unit.', 'APPROVED'),
  ('39c576d9-c966-511e-ad35-a51388f0ed15', 'cc8207b9-55c6-5f84-abd1-87278640b83b', 1, 'A number can be expressed in standard form as A times 10 to the power n, where 1 <= A < 10 and n is an integer.', 'APPROVED'),
  ('ab5fe0a9-4ba8-5ac9-a9a3-8585e153efeb', '2ff4ebab-2197-570b-96db-d18d598b5c2a', 1, 'Convert a numerical quantity from one SI-prefixed unit to another by applying the appropriate power-of-ten scale factor.', 'APPROVED'),
  ('8eec5c21-1a2b-5b62-b15d-dbe9cb846281', 'd4fbfa76-9c3c-5bb2-bfbf-6140e96564ad', 1, 'When multiplying two powers of the same base, add the indices; when dividing, subtract the indices; a fractional index represents a root.', 'APPROVED'),
  ('ec9d91aa-8850-5dc1-868f-4a53f0237400', '37acc94d-fcf9-5a13-9892-c8bc8dfd8af2', 1, 'In a right-angled triangle, the square of the hypotenuse equals the sum of the squares of the other two sides: a squared plus b squared equals c squared.', 'APPROVED'),
  ('5ea4af33-fd5a-5576-bbd6-cb78b0845971', '0b8c8b9c-c72b-5b06-b993-62f76694d2b0', 1, 'In a right-angled triangle, the sine, cosine and tangent of an angle are defined as the ratios opposite/hypotenuse, adjacent/hypotenuse and opposite/adjacent respectively.', 'APPROVED'),
  ('d5045894-d245-5762-9da2-bd573983dae1', 'aadb906f-8065-55e3-a4bf-25c849fed41f', 1, 'Use Pythagoras'' theorem to calculate an unknown side length of a right-angled triangle, given the lengths of the other two sides.', 'APPROVED'),
  ('9b3e36d3-0826-5916-aec6-798f4fdb248b', 'e36d54e2-0c98-59c4-bb63-bdd26d16f62e', 1, 'Use a trigonometric ratio (sine, cosine or tangent) to calculate an unknown side length or angle of a right-angled triangle, given sufficient other side lengths or angles.', 'APPROVED'),
  ('b452ffa5-eb7a-55c5-bb43-5b440fd54eb3', '46a960b2-1cd7-560e-bea8-cfefd10bc03b', 1, 'The mean of a set of numerical values is found by dividing their sum by the number of values, and is a measure of the central tendency of the data.', 'APPROVED'),
  ('25b0eb60-9d34-5318-acc1-026c5f1ca0b5', '175a4104-6c22-5673-8612-f551dda445bf', 1, 'The range of a set of numerical values is the difference between the largest and smallest values, and is a measure of the spread of the data.', 'APPROVED'),
  ('75e11ad5-6e47-5b72-9e8b-044d877da644', 'c4205908-aa16-5ad6-8d6e-6b919b4e679b', 1, 'The median of a set of numerical values, arranged in numerical order, is the middle value if there is an odd number of values, or the mean (average) of the two middle values if there is an even number of values; it is a measure of the central tendency of the data.', 'APPROVED'),
  ('51587a09-ffeb-5696-a5dc-c0ef2d7eda5c', '22f9266c-2972-57be-aaff-e39b04cd077b', 1, 'The mode of a set of numerical values is the value that occurs most often; a data set can have more than one mode.', 'APPROVED'),
  ('fee281bb-0593-5b21-aab1-68c23ea817a2', '398559d3-211d-5f99-ac95-5b52af8940be', 1, 'A force is a push or a pull that can change the motion, shape or state of rest of an object.', 'APPROVED'),
  ('0068b00c-bb40-5863-8934-f4fd442968a1', 'ea627d8f-ea59-5017-9365-e50421599f35', 1, 'Work is done when a force causes its point of application to move through a distance in the direction of the force.', 'APPROVED'),
  ('360be331-b54a-562b-a460-77c407617f98', '9322b703-e936-5b29-8e0c-60c61a47ff8e', 1, 'Work done is calculated by multiplying the force applied by the distance moved in the direction of that force: W = F times d.', 'APPROVED'),
  ('1bfb4cc2-43fa-5154-b767-7b70cb39657d', '4cec31ee-f4af-5d16-91a1-7cf3bf2a1c01', 1, 'Calculate the work done by a force from its magnitude and the distance moved in its direction, using W = F times d.', 'APPROVED'),
  ('0ebbad5a-1cc9-59b8-ab95-b847e4c68a74', 'a9930c23-8099-5e80-8fa5-58a7ea0992b2', 1, 'Energy is the capacity to do work, and exists in different forms including kinetic energy (due to motion) and potential energy (due to position or state).', 'APPROVED'),
  ('ef42a6ff-2415-5bba-b022-f3253f6007e8', 'a33c9601-bc3f-5759-bacd-98ed5f8087b8', 1, 'Energy cannot be created or destroyed, only transferred or converted from one form to another.', 'APPROVED'),
  ('413238e5-c026-57e9-af15-1d4a90e2595a', '9f2782ef-a9b3-53f6-b015-15c324e4a60b', 1, 'Kinetic energy is the energy an object possesses because of its motion.', 'APPROVED'),
  ('5c1c016e-5b83-55a9-a667-f8814e2551c7', 'f3414611-8ea4-5705-86de-059e0f326d21', 1, 'Kinetic energy is calculated from an object''s mass and speed using KE = one half times m times v squared.', 'APPROVED'),
  ('73a5f788-a422-50dd-8284-71a3e2e58588', 'fef2614a-a34d-5ddd-b2a7-af8f66e0b8b3', 1, 'Calculate the kinetic energy of an object from its mass and speed, using KE = one half times m times v squared.', 'APPROVED'),
  ('e6359b0c-4b07-5143-80ae-f5a835d8fad3', '995aff58-8a8d-500b-9559-e10e6f5a88c8', 1, 'Gravitational potential energy is the energy an object possesses because of its position (height) within a gravitational field.', 'APPROVED'),
  ('636dcd5b-e0f6-5911-bb13-9d60678952d9', '8eefce15-5555-5c67-8e76-b299b68e618e', 1, 'Gravitational potential energy near the Earth''s surface is calculated from an object''s mass, gravitational field strength and height using GPE = m times g times h.', 'APPROVED'),
  ('bc6ecfaa-c46b-5328-9710-5ec76d07b13f', '493241e6-1748-5113-b453-cfd5ed973964', 1, 'Calculate the gravitational potential energy of an object from its mass, gravitational field strength and height, using GPE = m times g times h.', 'APPROVED'),
  ('2ebe9571-0bb1-5a63-ad17-83fef6df16d1', 'baa0ac1c-29f6-5f4d-a345-a820c32215b1', 1, 'Power is the rate at which work is done or energy is transferred.', 'APPROVED'),
  ('f9427e38-2919-57ae-b917-dac18a40ce2b', '6fb81059-f7a4-5bdb-9bae-86903c460e64', 1, 'Power is calculated by dividing the work done (or energy transferred) by the time taken: P = W / t.', 'APPROVED'),
  ('8859ae3e-a3e2-5543-aac6-e668744413c1', '14b687f3-81be-581e-a017-e8bc76d0a1f9', 1, 'Calculate power from known work done (or energy transferred) and time taken, using P = W / t.', 'APPROVED'),
  ('b2b92d79-b4f1-53a4-8607-8e489039fe1b', '0c03af55-5181-5736-8058-b5904d7d54ea', 1, 'Efficiency is the ratio of useful energy or power output to total energy or power input, usually expressed as a percentage.', 'APPROVED'),
  ('e6a36e7a-0ee2-5f69-b10d-0dc5ce667dcb', 'c4ecff25-abd1-5111-8d3c-b2343faf5d12', 1, 'Calculate the efficiency of a process as a percentage from its useful output and total input.', 'APPROVED'),
  ('bed51c7f-fa0c-5061-87b3-f31020761492', '9d25890d-21a0-557e-a8f6-110e94fda134', 1, 'Mass is the amount of matter in an object, measured in kilograms.', 'APPROVED'),
  ('2994a02b-cc8c-524b-b640-2a1311b6eba6', '9cdc8a46-36f6-534a-bf2a-d24a32ff2a67', 1, 'Weight is the force of gravity acting on an object''s mass, measured in newtons.', 'APPROVED'),
  ('3315a2c4-28fe-50ac-b21c-95593e001db6', '2208b99a-be8f-5f98-bb70-b3ae666f6a46', 1, 'Weight is calculated from mass and gravitational field strength using W = m times g.', 'APPROVED'),
  ('e47c7a4e-6407-53fd-930a-be10947fca46', '3f4106b2-b45c-5c5b-b26e-c3435dad4951', 1, 'Calculate the weight of an object from its mass and gravitational field strength using W = m times g.', 'APPROVED'),
  ('8bee54cc-3b07-5146-87c2-3c64d591657d', '541450ba-23c2-54ad-a114-f46e0cd42ee5', 1, 'A simple machine such as a lever, gear or pulley provides mechanical advantage by changing the relationship between the effort (input force) applied and the load (output force) it moves.', 'APPROVED'),
  ('c053e733-f19f-50b1-9b04-147f3b6878fa', 'b9334553-8123-5c5c-86a3-50a2fe6e8d20', 1, 'A lever is a rigid bar that rotates about a fixed pivot (fulcrum); the mechanical advantage it provides depends on the ratio of the effort''s distance from the pivot to the load''s distance from the pivot.', 'APPROVED'),
  ('302f9a27-92d8-5fb6-afd6-1437c32590d3', 'd10be06a-a6ce-5a66-afeb-947945939aa3', 1, 'In a class I lever, the pivot is positioned between the effort and the load (for example a see-saw or a pair of pliers).', 'APPROVED'),
  ('c2c85dac-2a9b-5f69-8f69-dee6b42dee6a', '1017d1df-b2d1-5fce-9aed-e90bb877acbe', 1, 'In a class II lever, the load is positioned between the pivot and the effort (for example a wheelbarrow).', 'APPROVED'),
  ('157fa721-b931-5051-953d-4236b89f190f', 'da222087-68b8-5a46-8290-4db8b1c85fbf', 1, 'In a class III lever, the effort is positioned between the pivot and the load (for example a pair of tweezers or the human forearm).', 'APPROVED'),
  ('ee893c70-c169-5945-ba55-6f09dc2d1474', '638b37ec-9cc3-5d27-b45e-b8f336ca7ecd', 1, 'A lever is in balance (equilibrium) when the effort multiplied by its distance from the pivot equals the load multiplied by its distance from the pivot; this relationship can be used to calculate the effort needed to balance a known load, or vice versa.', 'APPROVED'),
  ('52e7cc02-c00a-53c3-ab83-073aa8b21c23', '72f07df6-00db-5c48-bda5-dc43c048393c', 1, 'A gear is a toothed wheel; when two gears mesh, their teeth engage so that one gear (the driving gear) transmits rotary motion and torque to the other (the driven gear) from one shaft to another.', 'APPROVED'),
  ('6df09c86-381e-5bd5-b701-d4c1c1508d3c', 'eada291a-bc7e-5f54-8aad-b83258c1a08e', 1, 'For two meshed gears, mechanical advantage (the ratio of output torque to input torque) equals the ratio of their radii (the driven gear''s radius to the driving gear''s radius); because gear teeth are evenly spaced and shared between meshed gears, a gear''s radius is proportional to its number of teeth, so this same mechanical advantage can equivalently be expressed as the ratio of their tooth counts (driven tooth count to driving tooth count).', 'APPROVED'),
  ('db18f7d0-675e-5aa4-a900-d20a23c6df23', 'e8e10b7b-190a-5cdd-9811-668e3edc8e5e', 1, 'A gear ratio can increase a mechanism''s output torque or its output speed relative to the input, but not both at the same time.', 'APPROVED'),
  ('55eb5d1b-6ab3-5d65-b7ea-a96cf791f571', 'da78399d-9a4a-52d9-b135-271a7295a099', 1, 'When two gears mesh directly, they rotate in opposite directions to each other.', 'APPROVED'),
  ('b86af614-4720-566a-84eb-ded876f07b35', '1bf090ad-8180-5ea4-91ff-38c59bf5fc3b', 1, 'An idler gear placed between a driving gear and a driven gear reverses the driven gear''s direction of rotation back to match the driving gear''s direction, without changing the overall gear ratio between them.', 'APPROVED'),
  ('25f24280-85e0-5b87-a8df-401d4ea37eb6', 'e16b37f0-cccf-57e0-abb2-aefd24997f20', 1, 'A pulley is a wheel with a grooved rim that changes the direction of a force applied through a rope or cable running over it.', 'APPROVED'),
  ('6d532931-c6de-5f16-8b4d-ebeee3ace792', '668e9d57-cb05-5e8f-b2f0-0098c7cdc257', 1, 'A single fixed pulley has a mechanical advantage of one -- it changes the direction of the effort but does not reduce the force needed; a movable pulley, or a combination of pulleys, can provide a mechanical advantage greater than one.', 'APPROVED'),
  ('a9785aea-f7a8-5c37-bdbb-294b5bab95b9', 'd35adcbe-499d-5d9a-9117-765062038f8c', 1, 'For a movable or combination pulley system, the mechanical advantage is approximately equal to the number of rope or cable sections that directly support the load.', 'APPROVED'),
  ('8a1043bf-35da-5ded-835d-a5fc1f777931', '2e744cb5-b7ba-5c6e-9413-716f0c12dc7c', 1, 'The mechanical advantage a pulley system provides in reduced effort force is accompanied by a proportional increase in the distance the effort must move to lift the load.', 'APPROVED'),
  ('2cfd8a8b-65ab-51d0-b257-7a8b2e20efa9', '83b70a8e-3336-5925-81af-a7b85f727bfe', 1, 'The metre (m) is the SI base unit of length.', 'APPROVED'),
  ('49b58dfb-ee5a-5967-81f5-a1b0a2292aff', 'a67272c6-48d5-5d2f-a9e8-69128136786a', 1, 'The square metre (m squared) is the SI derived unit of area, formed by multiplying two lengths.', 'APPROVED'),
  ('9c034eb6-f70a-570f-8bdb-1236a2ced52b', 'cce20c0c-b35c-532f-ad63-851aa65fc155', 1, 'The cubic metre (m cubed) is the SI derived unit of volume, formed by multiplying three lengths.', 'APPROVED'),
  ('aabafcfc-211f-51e0-90f4-03f814241b04', '26ae4273-d800-5d8d-bc1b-55605a8a29a9', 1, 'The kilogram (kg) is the SI base unit of mass.', 'APPROVED'),
  ('b61822a6-5f1c-5c09-b063-878fcdfcb950', '2f382cb6-bd12-553d-b5cd-704b0406db72', 1, 'Density is mass per unit volume, with SI derived unit the kilogram per cubic metre (kg/m cubed).', 'APPROVED'),
  ('5045a7a6-d291-5ee6-a33b-4dfc79398ecd', 'ab014fe9-ef87-5b3c-ac95-750b5582a1ec', 1, 'The second (s) is the SI base unit of time.', 'APPROVED'),
  ('cbb2e142-0278-5484-b64f-978644a786ff', '65adc28e-bf2d-58d8-b62c-f965398cb1b4', 1, 'The kelvin (K) is the SI base unit of thermodynamic temperature T; the degree Celsius (deg C) is a special name for the kelvin used to express Celsius temperature t, related by t = T minus 273.15. A temperature interval or difference of one degree Celsius equals one kelvin.', 'APPROVED'),
  ('44fe87e9-520d-58d5-ad5b-23ae96a68942', '32466eab-bea6-5b5d-bc4e-9a10f16bcff0', 1, 'The metre per second (m/s) is the SI derived unit of speed/velocity, formed by dividing a length by a time.', 'APPROVED'),
  ('d5e62039-c95e-5b3b-aa8d-eb6ac2eca381', '4b831e4d-9b3f-5d5a-bf28-465006c4716a', 1, 'The volt (V) is the SI derived unit of electric potential difference (voltage).', 'APPROVED'),
  ('5691a343-3b94-5511-a26a-cd050a77af2d', '4500bf66-9805-5b3c-8415-4c6939b18e35', 1, 'The ampere (A) is the SI base unit of electric current.', 'APPROVED'),
  ('1af58e76-fb60-506e-91d1-766fd2fd6209', '2d008420-bf74-5be1-82bc-22f570da1588', 1, 'The ohm is the SI derived unit of electrical resistance.', 'APPROVED'),
  ('e1d1fc0f-8160-51dd-afd3-71977ef00ebd', 'dd31d1c0-e7dd-54e1-b955-1e74d0984880', 1, 'The watt (W) is the SI derived unit of power.', 'APPROVED'),
  ('d2fd6e82-2c94-57f8-9969-53d97c5f3767', '1dedafc2-ae9e-5581-9c7b-d15f31ad253a', 1, 'The joule (J) is the SI derived unit of energy.', 'APPROVED'),
  ('036d3b87-953a-56c2-8e70-a417afb4d570', '3ccb78a4-da16-5f97-b044-78f0d9c31bbd', 1, 'The ohm-metre is the SI derived unit of resistivity.', 'APPROVED'),
  ('0815b1df-01e3-5cc6-bc4d-538ce9eedc5b', 'b97812cf-d15d-5532-abfb-24b58fdcc9ec', 1, 'Potential difference (voltage) is the electrical energy transferred per unit charge between two points in a circuit.', 'APPROVED'),
  ('122af4ac-5ae6-54db-b4d3-e639b434f117', 'cc4ab632-aaef-52ca-abcf-85bfe8d1b455', 1, 'Electric current is the rate of flow of electric charge through a conductor.', 'APPROVED'),
  ('19b281ed-fb2e-52f5-b0f6-bb7a9e5310dc', 'a7166df5-17e4-57aa-a96c-13803a058a0c', 1, 'Electrical resistance is the opposition a component presents to the flow of electric current.', 'APPROVED'),
  ('d54f3ca2-bbef-5c62-81ff-e58797224068', '38e2323e-cd52-583c-bba2-a574f8c71c38', 1, 'Resistivity is a material property describing how strongly a material opposes current flow, independent of the conductor''s length or cross-sectional area.', 'APPROVED'),
  ('c01dedb8-e629-5497-8077-725a981fdad6', '942699f4-4b54-5926-836c-a5c065845a61', 1, 'Electrical power is the rate at which electrical energy is transferred or converted.', 'APPROVED'),
  ('56d7298e-788a-5456-8221-61026a53d531', '2a15b94a-f956-5ac2-853f-40dd1c83e481', 1, 'Electrical energy is the total amount of electrical work done, or energy transferred, over a period of time.', 'APPROVED'),
  ('a8ac1853-3db1-51a4-921d-e38b52fb0c7f', 'dac6dfb4-3105-58d4-acb5-6c3c466f016d', 1, 'A voltmeter measures potential difference and is connected in parallel across the component being measured.', 'APPROVED'),
  ('ab2ca446-db40-5520-9f99-752c8fc9a464', '6419e664-81f7-5925-a1d7-b3c72004d803', 1, 'An ammeter measures current and is connected in series within the circuit being measured.', 'APPROVED'),
  ('19efd3ae-ec7f-593f-b3b9-c2641c5b4430', '5322f3db-b702-56a0-85c7-953e1e02a3b0', 1, 'An ohmmeter measures resistance, and must be used on a component that is isolated and de-energised.', 'APPROVED'),
  ('eae306be-b5d5-552a-98c7-8196e2a809bc', '62c7e41c-f87a-50cb-8550-01052e3f3356', 1, 'A wattmeter measures electrical power by combining a measurement of the current through the load with a measurement of the voltage across it; its output is proportional to the product of the two, giving power.', 'APPROVED'),
  ('e1fd6b7c-5ade-5e68-8a37-ae027d785039', 'f165b1d0-8993-56ff-9d10-1cd301b122c7', 1, 'An energy meter (kWh meter) measures the cumulative electrical energy delivered over a period of time, expressed in kilowatt-hours, by continuously measuring power and accumulating it over time.', 'APPROVED'),
  ('98f646f5-b346-57e4-97a5-4bb16418b82b', '8fa86128-8319-5741-839d-37bc327ed4de', 1, 'A multimeter is a single instrument that can be configured to measure voltage, current or resistance, by connecting one meter movement to different external resistor networks via a selector switch.', 'APPROVED'),
  ('8f43a424-fb53-54bf-a4e5-d00dcb477fe3', '030be6fd-ab5d-596d-adfd-ddc92fb90a67', 1, 'The power rating of an electrical device states the rate at which it is designed to convert electrical energy under normal operating conditions.', 'APPROVED'),
  ('4fb838ee-1139-5c70-aacd-2524e56d80d8', 'a0c2fc05-fcdb-5c7a-a5e7-4e1145ae4261', 1, 'The kilowatt-hour (kWh) is a practical, non-SI unit of electrical energy, equal to the energy transferred by a one-kilowatt load running for one hour, commonly used for billing electricity usage.', 'APPROVED'),
  ('ac60eda0-4ccc-51d9-8d84-3e031fc18007', '0aa97d64-619c-5951-a175-ab23faa01318', 1, 'The ampere is an SI base unit, while the volt, ohm, watt, joule and hertz are SI derived units formed from combinations of base units.', 'APPROVED'),
  ('041ec0a4-1f35-5246-8214-a528f7638bc6', '0f52dc67-0928-5ada-83af-e327cdee8893', 1, 'The hertz (Hz) is the SI derived unit of frequency, equal to one cycle per second.', 'APPROVED'),
  ('7b0ed897-7172-5604-b6f5-f69818c09bbf', '2e97f8f3-482a-56f1-9fdc-ff506066ee9e', 1, 'Frequency is the number of complete cycles of a repeating waveform that occur in one second.', 'APPROVED'),
  ('512efacd-4392-5430-94c0-3883a9b2c3ab', '4c49b779-369f-569b-9ee8-a7d27ba15f91', 1, 'Reactance is the opposition to current flow in an AC circuit caused by inductance or capacitance, and unlike resistance its value depends on the supply frequency.', 'APPROVED'),
  ('bb46ef1e-8e9a-53c5-be1c-c6599de22e57', 'e3ee57fb-3d4e-5895-bc22-2fd0f2d1e043', 1, 'Impedance is the total opposition a circuit presents to the flow of alternating current, combining resistance and reactance; like resistance and reactance, it is measured in ohms.', 'APPROVED'),
  ('5a474ad6-0f46-59c8-8932-7923f9119808', 'ad23fd61-1033-5341-bde9-b754621a195b', 1, 'The magnitude of the impedance of a series AC circuit is given by Z = sqrt(R^2 + X^2), where R is the circuit''s resistance and X is its net reactance.', 'APPROVED'),
  ('fa5d74bc-9e0b-5093-8e84-e8ddcf7dfac1', '5e578e42-a262-51c2-9c87-b7f3cca21651', 1, 'The henry (H) is the SI derived unit of inductance -- distinct from the ohm, the unit of inductive reactance.', 'APPROVED'),
  ('4c0099e9-4f70-598d-8f21-13127c24baeb', 'c3e5c6af-4d79-5889-860f-abcdba023d85', 1, 'Inductance is the property of a conductor or coil that opposes a change in current by storing energy in a magnetic field, measured in henries.', 'APPROVED'),
  ('7bd38461-ba5b-56c7-a8ba-64708cedbb1c', '9822b8a2-468f-56bf-a06b-6c9b6b036975', 1, 'Inductive reactance is the opposition an inductor presents to alternating current; it increases as supply frequency increases, and is measured in ohms (not henries, the unit of inductance itself).', 'APPROVED'),
  ('3629f6ba-0b37-5077-8148-15e4d30fc83a', '80f0971f-4bff-5286-86b6-a7d848b18cea', 1, 'The farad (F) is the SI derived unit of capacitance -- distinct from the ohm, the unit of capacitive reactance.', 'APPROVED'),
  ('cbdafdfc-d179-50fd-ad4f-eb6aab2208b9', 'a2efb5db-b5f6-5f74-86ca-e74e1e4776b0', 1, 'Capacitance is the property of a component that describes its ability to store electrical charge in an electric field, measured in farads.', 'APPROVED'),
  ('4bc9245c-69ba-5455-a140-8a7fb50758d3', 'd09863ef-9791-5bc4-a317-3096e2c1d938', 1, 'Capacitive reactance is the opposition a capacitor presents to alternating current; it decreases as supply frequency increases (the opposite frequency behaviour to inductive reactance), and is measured in ohms (not farads, the unit of capacitance itself).', 'APPROVED'),
  ('2b331e17-7dd9-550c-9ed1-e4cd412e2147', '0b54e39b-270a-5000-b236-676585c91f4c', 1, 'Power factor is the ratio of real (true) power to apparent power in an AC circuit; for a sinusoidal single-frequency supply, this ratio equals the cosine of the phase angle between voltage and current.', 'APPROVED'),
  ('9e224552-d3d1-5bfb-b5a1-d6a25f989f96', '75f72b0b-c547-5e3f-9628-4b5ee74e31dc', 1, 'The efficiency of an electrical device is the ratio of useful power output to electrical power input.', 'APPROVED'),
  ('b5ef7094-fc21-5974-a616-dbd7066980e4', '42109a19-62b1-5009-8865-5d616f877542', 1, 'Calculate the efficiency of an electrical device as a percentage from its useful power output and its power input.', 'APPROVED'),
  ('9b496243-13b7-5d52-b4dc-18f5cb1c8a50', '0d9f3ec4-6a91-5c9a-b31d-b823b6d944c1', 1, 'Electric current in a conductor is the flow of free electrons, driven by a potential difference across the conductor.', 'APPROVED'),
  ('66908ac3-06d3-5001-914a-7ffc20c6f8cf', '585c5f86-5167-539d-8d1d-272255785d4e', 1, 'A conductor is a material containing many free electrons, which allows electric current to flow through it easily.', 'APPROVED'),
  ('3bfbafe6-9f6d-5d8c-94ed-5e97ad288221', '7b2d32b9-b44a-58f7-bfe6-2e2c34a47c99', 1, 'An insulator is a material with very few free electrons, which strongly opposes the flow of electric current.', 'APPROVED'),
  ('cb016252-d3f7-5ac0-9e6c-1605dc46e029', '385e5c0c-8c7e-55d8-9018-241d19ab8ee6', 1, 'The resistance of a conductor is related to its resistivity, length and cross-sectional area by R = rho times L divided by A.', 'APPROVED'),
  ('c8d9a47b-f27e-5103-a20c-9675bd64b475', '02c60c25-6222-5f64-b878-fea5971cff63', 1, 'For a component obeying Ohm''s law, potential difference, current and resistance are related by V = I times R.', 'APPROVED'),
  ('8226e53c-9b92-5b88-812b-8a3849e46cdd', 'c563f2a7-2c6d-5a95-acff-3d3470e32e76', 1, 'At constant resistance, current is directly proportional to voltage; at constant voltage, current is inversely proportional to resistance.', 'APPROVED'),
  ('6c2705fc-c4a8-55bd-8c1c-db5642faa309', '7665a5cb-4b60-5fbc-bbc3-cb088fb95952', 1, 'Rearrange V = I times R algebraically to make voltage, current or resistance the subject.', 'APPROVED'),
  ('85ae192d-2662-5455-9cd5-33ec2d526e23', '0ff7ba9a-674b-5023-baaa-32d15a90ca94', 1, 'Calculate an unknown voltage from known current and resistance using V = I times R.', 'APPROVED'),
  ('40644492-b6de-512d-bdb7-eb1e3605317e', 'ac6dd2d2-89ce-5c36-a188-a6dfe5048165', 1, 'Calculate an unknown current from known voltage and resistance by rearranging and applying V = I times R.', 'APPROVED'),
  ('7a0915af-7fd9-575b-9926-0ebb9febb146', 'ef24e022-c569-555d-99b5-0b197ec663e1', 1, 'Calculate an unknown resistance from known voltage and current by rearranging and applying V = I times R.', 'APPROVED'),
  ('0f93828a-546f-5133-b4f6-27e3b793040d', '4f6b9e82-69a2-5afc-b576-41a2535b2b52', 1, 'In a series circuit, components are connected end-to-end so that there is only one path for current to flow.', 'APPROVED'),
  ('ac0a79b6-7600-5d24-9d09-2ae917a4e6c0', 'cb6c95b2-2f6e-5df0-9312-b0360b5c3f12', 1, 'In a series circuit, the same current flows through every component.', 'APPROVED'),
  ('b5b3968b-0edc-569e-95dd-daefbafa5f20', 'cfb629ad-faf3-516c-a555-2fdfa7007f9f', 1, 'The total resistance of resistors connected in series is the sum of the individual resistances: RT = R1 + R2 + ...', 'APPROVED'),
  ('97032cf1-ad69-5940-9d84-c63aebba5fb8', '3e00d92d-7918-5741-a285-2d4777537e14', 1, 'Calculate the total resistance of resistors connected in series.', 'APPROVED'),
  ('be4c4ea8-0648-5cfd-baf3-8e54b77a63e5', '669141fd-0bec-5620-abf4-a378c55b7717', 1, 'A calculated total resistance for resistors in series that is less than the largest individual resistance indicates a calculation error, since total series resistance is always at least as great as the largest individual resistance.', 'APPROVED'),
  ('ae563cae-df83-5d03-9659-e927a595af37', 'd4405fa2-d8dd-5bc9-b40f-ea633a2e5200', 1, 'Voltage drop is the reduction in potential difference across a component or conductor caused by current flowing through its resistance.', 'APPROVED'),
  ('040512b5-ed59-560d-9763-b59c770a2b1a', '538293c5-f4a2-578b-8e7f-034ba39bfa32', 1, 'In a series circuit, the supply voltage is shared between the components as individual voltage drops that sum to the supply voltage.', 'APPROVED'),
  ('41d74f9c-ac85-5983-979b-eb3832cd23e6', '67811700-e90e-570c-bcd5-f525b9a588a8', 1, 'Kirchhoff''s voltage law states that the algebraic sum of the voltages around any closed loop of a circuit is zero -- in a series circuit this means the individual voltage drops sum to the supply voltage.', 'APPROVED'),
  ('7ab007c5-ae53-5ece-84ac-f0d8c8d20b65', 'd562f9be-0f24-50e5-b5e6-b1d34ab84d91', 1, 'Calculate an individual voltage drop across a component in a series circuit.', 'APPROVED'),
  ('1b8bde6a-5404-5315-a91c-c38bb4b87f89', 'e5944629-d58a-56d9-b555-94c47b13c853', 1, 'In a parallel circuit, components are connected between the same two points, providing more than one path for current to flow.', 'APPROVED'),
  ('c0a86e32-81c3-5dea-9dcf-f5fa61fa4f32', '3245d391-6bd0-5e06-8684-a0bd98eb02f9', 1, 'In a parallel circuit, the potential difference is the same across every branch.', 'APPROVED'),
  ('a2a34864-0f3e-5f6f-aeb1-4a1370e7926c', '1980ff3f-afd0-5aec-99da-2861480206ff', 1, 'In a parallel circuit, the supply current divides between the branches, and the branch currents sum to the total current.', 'APPROVED'),
  ('26c8e641-4536-5df1-97bc-fea7c8b95e1a', 'b2f2ad17-7466-5d91-97a1-6e9220a881eb', 1, 'Kirchhoff''s current law states that the algebraic sum of the currents entering and leaving any point in a circuit is zero -- in a parallel circuit this means the branch currents sum to the total supply current.', 'APPROVED'),
  ('1ebb03ec-0416-55cf-8173-dd02a4ae26ab', 'dc2b0223-9440-51d2-b5e0-82a7115adc03', 1, 'The reciprocal of the total resistance of resistors connected in parallel equals the sum of the reciprocals of the individual branch resistances.', 'APPROVED'),
  ('e7b2ded7-9814-51df-b46d-0a8a9f089f22', '6248484f-5478-525d-898b-cf47972cb1df', 1, 'Calculate the total resistance of resistors connected in parallel.', 'APPROVED'),
  ('0115758a-c9c9-5e3b-92ab-a6af6c5e5f14', 'd7d0d3e7-e2eb-5d88-a352-6c7c41e18686', 1, 'A calculated total resistance for resistors in parallel that is greater than the smallest branch resistance indicates a calculation error, since total parallel resistance is always less than the smallest branch resistance.', 'APPROVED'),
  ('97b8a2d2-4596-514e-bc71-09b80ccf0fd0', '2a593d33-bb38-591b-9673-089560be441e', 1, 'Calculate an individual branch current in a parallel circuit.', 'APPROVED'),
  ('ced0f110-8b63-5ebf-b1a1-b75468179d2a', '4beaac02-6059-592c-a6ad-24615b734d59', 1, 'Electrical power is related to voltage and current by P = V times I.', 'APPROVED'),
  ('30a2e2b2-3278-5aaf-bcf8-c0f315712b9c', 'ea93e795-f652-56a4-9664-47845fd33368', 1, 'Rearrange P = V times I algebraically to make voltage or current the subject.', 'APPROVED'),
  ('857af299-c421-5567-b489-afe1e1a8d528', 'fe898c30-349c-5e9f-8674-a91541631a36', 1, 'Calculate electrical power from known voltage and current using P = V times I.', 'APPROVED'),
  ('8038ee14-ea0f-5093-8576-caad64496727', '3fc26d7b-a370-5ddb-b5bc-63b74aa7e5c3', 1, 'Electrical power can also be found from current and resistance alone, since combining P = V times I with V = I times R gives P = I squared times R.', 'APPROVED'),
  ('dbf872a8-a4a2-5019-8b64-906230e45208', 'e764f805-828d-5115-b0ae-75da8f68f466', 1, 'Calculate electrical power from known current and resistance using P = I squared times R.', 'APPROVED'),
  ('3f4041fe-0a47-5685-aa0f-860b3fed6cc8', 'd0649708-33e4-54ab-8dc5-57e508a29825', 1, 'The total power dissipated in a circuit is the sum of the power dissipated in each individual component, regardless of whether the components are connected in series or parallel.', 'APPROVED'),
  ('8851c42f-efa6-537e-b81a-6d0fce4ed7dd', '63f31ee2-4cb8-50a3-aca5-262c7acd73a1', 1, 'Current flowing through a resistance causes heating, because electrical energy is converted into heat energy.', 'APPROVED'),
  ('ddfe7564-ae3c-5c28-83b6-6ffe5aaa9caa', 'b0e7ec2c-0632-5522-a7bf-72d800de5b5e', 1, 'Current flowing through certain solutions (electrolytes) causes chemical changes, a process known as electrolysis.', 'APPROVED'),
  ('759819ac-910e-5508-aa09-0a43b39f4c71', '449775a8-cf30-5e5f-accf-290fdc689095', 1, 'Electric charge is a fundamental property of matter that causes it to experience a force in an electric field, and can be positive or negative.', 'APPROVED'),
  ('d2e8e334-7b4d-5769-b9f6-83911617cfa5', '1c1e5521-5b22-5f04-8e50-a3f2b0520168', 1, 'An atom consists of a nucleus containing positively charged protons, surrounded by negatively charged electrons; in a conductor, some of these electrons are only loosely bound to their atoms and are free to move.', 'APPROVED'),
  ('034c5fae-8836-5c9c-9bed-82ba51fad2af', '64b4144b-c71f-5257-997d-5e95778ef742', 1, 'The coulomb (C) is the SI derived unit of electric charge.', 'APPROVED'),
  ('f8b4341a-ceda-5368-8795-78b956b2ce6c', 'fc5282bc-0a95-5cc3-914b-4b0c2c1525f4', 1, 'Electric current equals the rate of flow of charge: I = Q divided by t.', 'APPROVED'),
  ('65515c79-ec7f-5886-884b-917f2d9da44d', 'd74fa4f4-c971-544d-bc9c-0ffaf7747033', 1, 'Calculate charge or current from the relationship I = Q divided by t, given the other two quantities.', 'APPROVED'),
  ('41195aa7-53a8-56a4-8ac5-3de5027ed72b', '34e97d66-d2e6-5dcd-ba51-541bfc6312fb', 1, 'Common conductors used in electrical installation work include copper and aluminium; common insulators include PVC and rubber.', 'APPROVED'),
  ('d2d21edb-81c5-51d5-9b34-dd7a6eb18238', 'dfc25505-46de-5051-96a9-ef276209c96f', 1, 'The resistance of a conductor depends on its length, its cross-sectional area, its resistivity and its temperature.', 'APPROVED'),
  ('e5ad8af5-4302-5caf-86e3-6910e0d1a636', '556b6ddd-49de-5cca-b19f-e80d8b8b28cb', 1, 'Compare the resistivity of different materials to determine which is the better conductor: a lower resistivity indicates a better conductor.', 'APPROVED'),
  ('83e94558-8e33-5d67-a1e4-7d3e795f7f30', 'f6088add-1c59-5535-9e15-577ed563bc55', 1, 'Increasing the length of a conductor increases its resistance, since resistance is directly proportional to length.', 'APPROVED'),
  ('99237dbe-957d-5e6a-b67c-005276b0f91c', '89c16a6d-8a89-5008-a8c4-1e962417e01f', 1, 'Increasing the cross-sectional area of a conductor decreases its resistance, since resistance is inversely proportional to cross-sectional area.', 'APPROVED'),
  ('399b6ad7-76bb-5360-8fcd-dee01f774dcd', '4b8c447f-6e7e-51ed-bd95-eac1cf329fb6', 1, 'If the voltage across an insulator becomes too high, the insulator can break down and allow current to flow, which is why insulation has a rated maximum voltage.', 'APPROVED'),
  ('1f22c3f6-64fa-5cb4-9935-5a994e658047', '0306a674-5d80-56ed-a7c2-49b408a455b8', 1, 'Select the correct arrangement of V = I times R to use, based on which two quantities are known and which quantity is required.', 'APPROVED'),
  ('83446b5c-45d0-5b33-ac9b-cdd0447d5caf', '29bc29e0-9166-58fb-80a4-9d2275a3b444', 1, 'Identify whether a given circuit diagram or description shows components connected in series or in parallel.', 'APPROVED'),
  ('45144705-69e4-59cd-8197-e64092d688f8', '01384db1-0a88-5d19-8122-49fe8dab0011', 1, 'The equivalent resistance of a network of resistors is the single resistance value that would draw the same current from the same supply voltage as the whole network.', 'APPROVED'),
  ('d14810a4-54f8-5306-ab3a-c2933b5e4533', '1b07ad29-1def-53cf-a4b5-3b78009e5d48', 1, 'Some circuits combine both series-connected and parallel-connected sections within the same network.', 'APPROVED'),
  ('5859b01a-08d0-559f-9997-0bd8b94198b5', '19add2e2-b48a-56d8-b304-2115a02e50d6', 1, 'Trace the path or paths current takes through a given series or parallel circuit diagram.', 'APPROVED'),
  ('8b303362-916f-5572-8315-81b90535461f', '330b4447-c051-561d-b843-663661152cdb', 1, 'Compare how the total resistance of the same set of resistors differs when connected in series versus in parallel: the parallel total is always lower than the series total.', 'APPROVED'),
  ('5481c9da-89d5-5401-8518-b3fac9e1ed82', 'f4ce4e02-952a-5a34-b6af-39e2c2971594', 1, 'Compare current behaviour in series versus parallel circuits: current is the same throughout a series circuit, but divides between branches in a parallel circuit.', 'APPROVED'),
  ('1e7337ad-643b-5fae-96ab-5adefffff4b7', '43357179-f766-5fbf-910f-753f14e356c5', 1, 'Compare voltage behaviour in series versus parallel circuits: voltage divides between components in a series circuit, but is the same across every branch of a parallel circuit.', 'APPROVED'),
  ('1f1ef6db-3c9c-5d60-a6d9-4a1b13289fdb', '4cbd59c8-f70f-5e6c-82e4-9895792f4205', 1, 'Compare the total power dissipated by the same set of resistors at the same supply voltage when connected in series versus in parallel.', 'APPROVED'),
  ('5d7c142c-48de-51de-b66a-5cf35d0df071', '7ca08968-59ad-5a44-b190-13a430938041', 1, 'Compare the total electrical energy transferred over a given time by the same set of resistors when connected in series versus in parallel at the same supply voltage.', 'APPROVED'),
  ('bbf11a72-9ed6-52c0-b8bd-3fc2600b7067', '94b40935-39ff-55be-9dcf-a52c31985417', 1, 'In a series circuit, since current is equal throughout, the component with the greatest resistance has the greatest voltage drop and dissipates the most power.', 'APPROVED'),
  ('54beb3b2-be72-539f-bacc-8b40f94d2628', '991f14bb-1f46-5cc9-9f8e-207d148972a9', 1, 'In a parallel circuit, since voltage is equal across every branch, the branch with the smallest resistance carries the largest current and dissipates the most power.', 'APPROVED'),
  ('ad468aa1-e0a6-5323-aa13-02d612b6757e', '148ac7cf-e088-5156-842d-c8121653a5c7', 1, 'Predict the effect on current if a series circuit is broken (open-circuited) at any point: current stops flowing throughout the whole circuit.', 'APPROVED'),
  ('1df60088-9f6d-5209-9e2c-49da606e87f5', '297c9395-fbf6-5315-bb5b-bfb7db589a76', 1, 'Predict the effect on the remaining branches if one branch of a parallel circuit is broken (open-circuited): current continues to flow unaffected in the other branches.', 'APPROVED'),
  ('58237c2a-149c-530b-832e-212f718c2760', '6538f2b7-abb1-5a60-99d7-e144473f6940', 1, 'Predict the effect on supply current of adding an extra resistor in series: total resistance increases, so supply current decreases.', 'APPROVED'),
  ('7bc47499-7430-5098-a5f5-a55536dff768', 'ed3251e6-d562-56ed-b17e-cc16a790f6f3', 1, 'Predict the effect on supply current of adding an extra branch resistor in parallel: total resistance decreases, so supply current increases.', 'APPROVED'),
  ('3049df19-32fc-52b1-8dda-da8ce63a06e4', '463420a0-1db4-50c8-b0d4-fd62261508b7', 1, 'Recognise a short circuit as an unintended low-resistance path that causes abnormally high current to flow.', 'APPROVED'),
  ('b4edad2b-a970-5186-964a-e4ad152889de', '50eded94-54ad-5685-8d37-f90e53b08eef', 1, 'Recognise an open circuit as an unintended break in the current path that prevents current from flowing.', 'APPROVED'),
  ('cbad0e46-7803-5bed-857c-402dc745211d', '071afae9-300d-53e4-995b-de9bd38ad4ab', 1, 'Predict the effect of a short circuit occurring across a component: current increases sharply and may cause damage or operate a protective device.', 'APPROVED'),
  ('016b172e-b0d2-5e35-9c89-4afb9bbf7a06', '0085b333-93bd-56d3-ab3a-3a2ad2fb1974', 1, 'A protective device, such as a fuse or circuit breaker, is designed to automatically disconnect a circuit when current exceeds a safe value.', 'APPROVED'),
  ('6601a9ef-da67-5bbf-834c-f0547e01cbdd', 'dfe24bbf-f5b6-5265-8c75-596bdd8ecc10', 1, 'A fuse protects a circuit by melting and breaking the circuit when current exceeds its rated value, using the thermal effect of current.', 'APPROVED'),
  ('41bff82e-b36d-5857-881a-3b64b6125f27', '829a7e9a-fcd9-5a0a-9893-d2c1833fc631', 1, 'Recognise practical applications of the thermal effect of current, such as heating elements and filament lamps.', 'APPROVED'),
  ('6de15f37-f5bd-5390-b7d5-5ca94020c92b', '8a4ca08d-e2d3-5941-83fc-8ac5d22da1b7', 1, 'The amount of heat generated by current flowing through a resistance depends on the current, the resistance and the time for which the current flows.', 'APPROVED'),
  ('9543f5e4-503e-5012-931e-fc01d33d4459', 'd8bff119-82bc-50f7-ac1f-bde1fea7b373', 1, 'Compare a fuse, which must be replaced after operating, with a circuit breaker, which can be reset and reused after tripping.', 'APPROVED'),
  ('b1861537-4e76-544d-982e-3e10e7f00551', '8974b996-c419-57d1-8358-fa1601d66a3a', 1, 'Select the appropriate instrument (voltmeter, ammeter, ohmmeter or multimeter) to measure a given electrical quantity.', 'APPROVED'),
  ('d2f2e834-35ad-559c-bc2c-c2fdb72ee3af', '8930de8a-14a3-596e-9ab2-6055a5e583dd', 1, 'An ideal voltmeter has very high internal resistance so that connecting it in parallel does not significantly alter the circuit being measured.', 'APPROVED'),
  ('b6c094fd-664f-55ef-9c0c-d75ad42a8c59', 'ffc1a961-ff76-5985-8281-3586c95fc481', 1, 'An ideal ammeter has very low internal resistance so that connecting it in series does not significantly alter the circuit being measured.', 'APPROVED'),
  ('0544eb99-f517-5453-b106-b7dba9acf7fa', '10b77dda-1568-5213-ad0d-9e06f7656556', 1, 'A continuity test uses an ohmmeter or multimeter to confirm that a low-resistance path exists between two points in a de-energised circuit.', 'APPROVED'),
  ('4fd1b99f-f78c-5317-bbfc-86cc2dab0773', 'da1aa5be-fa84-5ae9-858f-2e272bfc612b', 1, 'A series circuit of two or more resistors can be used as a voltage divider, where the voltage across each resistor is proportional to its resistance.', 'APPROVED'),
  ('17b471fd-68f4-5964-9454-43d1c033b9dc', '298778f1-a8cc-5b5b-8d9d-92d8f3180beb', 1, 'A parallel circuit of two or more resistors divides the total current between branches in inverse proportion to their resistance.', 'APPROVED'),
  ('77de0953-d8ed-585f-beb3-f45ce6663cc9', '03dea5bc-aa7e-5a88-b260-1b70cc44d7c5', 1, 'Calculate the supply current in a series circuit from the supply voltage and the total resistance of the circuit.', 'APPROVED'),
  ('abc5f1b5-fe52-502b-ba6e-a4c0fea14418', '76602fe2-4e0c-5169-b646-d712b47c48f6', 1, 'Calculate the supply current in a parallel circuit from the supply voltage and the total resistance of the circuit.', 'APPROVED'),
  ('58511e05-da86-5bdf-87fc-ef2daeff12d3', '2a8cbaad-161e-5c37-a874-c45f5217b06a', 1, 'Electrical power can also be found from voltage and resistance alone, since combining P = V times I with I = V divided by R gives P = V squared divided by R.', 'APPROVED'),
  ('38f1196a-b7a1-5b87-b4c3-68ccf38acd5b', '7298383b-6573-5217-8f66-d4c63ec135ac', 1, 'Calculate electrical power from known voltage and resistance using P = V squared divided by R.', 'APPROVED'),
  ('1abbdf13-3491-55fd-be10-cb94b7f45d53', '10a3bf46-8575-56fa-8c74-bc7892827576', 1, 'Calculate the power dissipated by an individual component in a series circuit from the common current and that component''s resistance.', 'APPROVED'),
  ('54f5986f-439d-59d6-ac63-66791502fe06', 'e234c1c4-3ff1-53e1-9c24-96a6b1b411e0', 1, 'Calculate the power dissipated by an individual branch in a parallel circuit from the common branch voltage and that branch''s resistance.', 'APPROVED'),
  ('65bb6083-c722-5454-a7b7-99fb85df156c', '39db63c9-c297-503c-a6e2-4608da3f0cef', 1, 'In a series circuit, since current is equal throughout, the component with the greatest resistance dissipates the most power.', 'APPROVED'),
  ('ed1062b6-86f5-5a3c-abc4-6f20d4c933f5', '9a5a925d-57c8-5a81-8799-c8119b8a04e9', 1, 'In a parallel circuit, since voltage is equal across every branch, the branch with the smallest resistance dissipates the most power.', 'APPROVED'),
  ('025d026e-9173-5e3b-ad54-3be1d60c1377', '6ff30845-1907-56d1-a6d7-beca945255af', 1, 'Electrical energy transferred is calculated by multiplying power by time: E = P times t.', 'APPROVED'),
  ('ae93f7e5-4a15-5789-a2f9-0e31c8b0d25a', 'a14919cb-bb40-5ea9-96f9-d4a93376ecbd', 1, 'Rearrange E = P times t algebraically to make power or time the subject.', 'APPROVED'),
  ('bb7979f1-8bf6-5843-a3b4-feed51ff2046', 'b85d6c08-65e2-5374-bc13-b066b708a574', 1, 'Calculate the electrical energy transferred by a device from its power rating and its time of use, using E = P times t.', 'APPROVED'),
  ('b75877db-2597-5858-970b-6f492fc6e43a', 'fa477bbd-af67-5fad-a0c5-b2a2408a474d', 1, 'Calculate the electrical energy used by a device in kilowatt-hours from its power rating in kilowatts and its time of use in hours.', 'APPROVED'),
  ('4fac86bb-776d-5f41-8e20-730a9e467843', '9c95632e-4392-5f52-b8e5-3d668e86f041', 1, 'Magnetism is a force of attraction between unlike magnetic poles and repulsion between like magnetic poles.', 'APPROVED'),
  ('b0204286-8b37-5ad9-89a7-22d17e26b22c', '127c100f-9d74-50bd-9729-82664fd60f97', 1, 'Magnetic flux is a measure of the total amount of magnetic field passing through a given area.', 'APPROVED'),
  ('406a5d42-9765-59e4-9fdc-116487e91c5e', 'e8275439-3686-5c53-9079-98b9b99bc5bf', 1, 'The weber (Wb) is the SI derived unit of magnetic flux.', 'APPROVED'),
  ('a5b15d4f-1a8f-5449-b117-855a4d0e8f22', 'c50dba05-380b-5cb8-aa4a-e94044806c12', 1, 'Magnetic flux density is the amount of magnetic flux passing through a unit area, describing how concentrated a magnetic field is.', 'APPROVED'),
  ('2a862d49-c931-576b-a05d-89538c6c7d0d', 'b30fb0e5-6d2c-58a4-9457-03c408c7e389', 1, 'The tesla (T) is the SI derived unit of magnetic flux density.', 'APPROVED'),
  ('552cc036-f79d-5f5c-9d87-ad456da6ba57', '0e2a7381-35c7-533d-aac7-ad198034e247', 1, 'A current-carrying conductor produces a magnetic field around it.', 'APPROVED'),
  ('cc4ceef8-f0c0-5285-b08d-08f851491302', '90663f28-956e-5e6c-9472-8ffb70e1bfb3', 1, 'The direction of the magnetic field around a straight current-carrying conductor is given by Maxwell''s screw rule (equivalently, the right-hand rule): with the thumb pointing in the direction of current flow, the curled fingers give the direction of the circular field around the conductor.', 'APPROVED'),
  ('2dc81f39-959e-5415-92b8-e821ce296ee8', '77588b98-9eda-594b-88eb-8a85cf9de895', 1, 'A current-carrying conductor placed in a magnetic field experiences a mechanical force.', 'APPROVED'),
  ('0720bacb-25c8-5e26-8634-6e2895332d0e', 'a45aebe5-5b70-53c2-a81d-83afadc1bc04', 1, 'The magnitude of the force on a straight current-carrying conductor at right angles to a magnetic field is given by F = B I l, where B is the magnetic flux density, I is the current and l is the length of the conductor in the field.', 'APPROVED'),
  ('d410cc25-e784-5f83-8dd4-638a7ee530dd', 'cce32487-1d84-56e9-b24c-098a6d300eac', 1, 'Fleming''s left-hand rule gives the direction of the force on a current-carrying conductor in a magnetic field: with the First finger, seCond finger and thuMb of the left hand mutually at right angles, the First finger points along the Field, the seCond finger along the Current, and the thuMb gives the direction of Motion (force).', 'APPROVED'),
  ('ed8ad86f-e2e9-59dd-83b5-61aaae1a7bef', 'e19d0673-ee6a-59fd-8bd6-5470ba803c84', 1, 'Electromagnetism is the branch of physics concerned with the relationship between electric current and magnetic fields, including how one can produce the other.', 'APPROVED'),
  ('73a54cfa-d251-532a-9b13-dbcfb4fe8b38', '53c974fd-e6e9-50d8-ae6b-d26d49747a46', 1, 'Electromotive force (EMF) is the electrical energy per unit charge supplied by a source, which drives current around a circuit.', 'APPROVED'),
  ('7f950442-bcac-50e2-b97d-b2426c55f004', '25d938b9-3f99-5854-8de1-baa436cfda69', 1, 'For a straight conductor of effective length l moving through a magnetic field of flux density B, the magnitude of the induced EMF is given by e = B l v (where v is the conductor''s velocity) when the conductor''s length, its velocity and the magnetic field are all mutually perpendicular (at right angles) to one another.', 'APPROVED'),
  ('88564b14-1573-5bd5-8e63-a367d0b1352c', '111ed4bf-1b71-54b0-91a6-bc69d4f9a717', 1, 'Fleming''s right-hand rule gives the direction of the current induced in a conductor moving through a magnetic field: with the thumb, First finger and seCond finger of the right hand mutually at right angles, the thumb points in the direction of Motion, the First finger along the Field, and the seCond finger gives the direction of the induced Current.', 'APPROVED'),
  ('107e2bf8-6077-5294-bcae-a619ff84c8de', 'e446ce72-03a8-5956-a5f4-79915e31001e', 1, 'Terminal voltage is the potential difference measured across the terminals of a source while it is supplying current, which is slightly less than its EMF due to the source''s own internal resistance.', 'APPROVED'),
  ('7412ca76-d90b-5d2e-8bca-9d1bbe2457f3', '9c9f16aa-8a01-5d8f-9572-22e3847d0596', 1, 'A changing magnetic flux through a circuit or coil induces an electromotive force (EMF) in that circuit -- the principle of electromagnetic induction.', 'APPROVED'),
  ('364588c5-90ca-5ef2-b150-ab94710b8901', 'e6de5434-449b-5fda-8fb7-bf62b9c4ff99', 1, 'The magnitude of the EMF induced in a single loop equals the rate of change of the magnetic flux through it: e = (change in flux) / (time taken).', 'APPROVED'),
  ('ee98c671-24d0-555e-81fc-d940e7b70a85', '9e9e8db4-5929-5f03-b655-ad3e0486adbc', 1, 'A simple AC generator produces an alternating EMF by rotating a single loop of wire at constant speed within a magnetic field, continuously changing the flux linking the loop.', 'APPROVED'),
  ('83ccc1b8-39a8-5a23-a898-add935dac4ff', '93a8e1a1-fa11-578f-93c8-7f365b4193bf', 1, 'The EMF produced by a simple rotating-loop AC generator varies with time as a sine wave.', 'APPROVED'),
  ('4ffda951-944b-584c-ba7f-75d9d4639a75', 'ff701cb6-927c-5931-b783-04e5f61c1794', 1, 'Direct current (D.C.) flows in one direction, and its magnitude may be steady or may vary (as with pulsating D.C.); alternating current (A.C.) periodically reverses direction and ordinarily varies in magnitude, typically following a sine wave.', 'APPROVED'),
  ('49120035-caf2-5c4c-a7c7-508205f845d9', '9f5d5463-96ee-5323-94fd-44c67e70e928', 1, 'UK domestic and industrial electrical supplies are alternating current, with a standard frequency of 50 Hz.', 'APPROVED'),
  ('54e413f4-6444-599d-ac59-0adaea4f34e6', 'b6c4769f-daa4-59f3-8839-6dde62628993', 1, 'Periodic time is the time taken to complete one full cycle of a repeating waveform.', 'APPROVED'),
  ('dfed0d48-fe15-5dde-8140-60971101cc06', 'e713aafb-5039-5534-8c1e-6e622ef12bbf', 1, 'Amplitude is the maximum displacement of a waveform from its zero (mean) value.', 'APPROVED'),
  ('649fdb54-519c-53d5-88dd-0cbefc9ea526', '4eb1cbd8-de4d-5206-b758-2105f88b812f', 1, 'The peak-to-peak value of a waveform is the difference between its maximum positive and maximum negative values.', 'APPROVED'),
  ('8931ff48-c0dc-5dff-b7a7-ea59caa0e0eb', 'c1c09956-b9b2-582a-a2fb-a77d92df4713', 1, 'The RMS (root mean square) value of an alternating quantity is the value of direct current or voltage that would produce the same heating effect in a resistor.', 'APPROVED'),
  ('b85ce211-6582-5319-bffe-ebe44cda20ce', '02e7e5b9-7cda-5520-8103-f2e5d5e5fd33', 1, 'The average value of an alternating waveform used in AC calculations is normally the average of the rectified (half-cycle) waveform, rather than the average over a full cycle.', 'APPROVED'),
  ('f2ac17aa-c0e1-5aeb-bb92-f95271cdc61a', '524b212e-0b06-59f1-b205-07788f916a96', 1, 'The average value of a symmetrical sine wave taken over a full cycle is zero, because the positive and negative half-cycles cancel; the non-zero ''average value'' quoted for AC calculations refers to the rectified waveform.', 'APPROVED'),
  ('3dc25e09-1008-54d5-aff8-3db32b815b98', 'd94d3db7-a162-508c-8653-af0b8f50af95', 1, 'For a pure sine wave, the RMS value equals the peak value divided by the square root of two.', 'APPROVED'),
  ('87acd920-543a-58e4-91bc-823525e3d3f0', 'e97e7eca-2253-5576-ab0e-1c7a468e360c', 1, 'Calculate the RMS value of a sine wave from its peak value, or the peak value from its RMS value.', 'APPROVED'),
  ('a5e4c675-1360-513f-a675-412a0d6ea84b', '2d1cb19f-12b7-5ee8-84c5-5b74cc1b20ab', 1, 'The rated voltage of an AC supply (for example 230 V) refers to its RMS value, not its peak value, which is higher.', 'APPROVED'),
  ('ad831efc-100d-5c7e-906e-1fd59ffd0e1c', '256599fb-5d32-55cf-9aba-bf4b9e02129c', 1, 'Frequency and periodic time are reciprocals of each other: frequency equals one divided by periodic time.', 'APPROVED'),
  ('2831ca92-b26b-5d99-89b8-a690cf4d27d5', '8f0cc64c-574a-5a7d-a8ff-840a41b4a64f', 1, 'Calculate frequency from periodic time, or periodic time from frequency, using their reciprocal relationship.', 'APPROVED'),
  ('a2a3a54f-966e-5fc2-acaa-7cca91019215', '085e9772-e1ce-50ab-844f-2432204f3785', 1, 'Compare a permanent magnet, which retains its magnetism without a current, with an electromagnet, whose magnetic field depends on a current flowing through a coil.', 'APPROVED'),
  ('c6601fd2-4157-59d1-b9c2-7eea81fdb6ad', 'e53af8d4-0503-5c9e-a577-5c828bc25381', 1, 'A clamp meter measures current without breaking the circuit, by detecting the magnetic field produced around the current-carrying conductor.', 'APPROVED'),
  ('d4b13b57-dc60-57f3-a710-9a524c05bb11', 'b00c1bc5-9a99-5d37-bba2-55662bbbd0ea', 1, 'An electric motor uses the force on a current-carrying conductor in a magnetic field to produce rotational motion.', 'APPROVED'),
  ('be4f1d6e-4dbb-5063-a7c4-8d8bd59647a2', 'ecabeab4-5814-5dd1-98cb-2ea693cd86c4', 1, 'Compare an electric motor, which converts electrical energy into mechanical motion using force on a current-carrying conductor, with a generator, which converts mechanical motion into electrical energy using electromagnetic induction.', 'APPROVED'),
  ('94b5764c-c952-5e15-b6b8-87f454b5c62d', 'c08313e2-5ec3-5231-93eb-11beda090d9b', 1, 'An oscilloscope displays how a voltage varies with time, allowing the shape, amplitude and periodic time of a waveform to be observed.', 'APPROVED'),
  ('15a1076f-8308-5d65-b744-fdc6c10a52cd', 'f0a8daef-57b3-5897-bc7f-e0b95dc37688', 1, 'Compare how a resistor behaves the same way under AC or DC supply (Ohm''s law applies using RMS values), while an inductor or capacitor''s opposition to current depends on whether the supply is AC or DC.', 'APPROVED'),
  ('d09fe6e3-67ee-5bcb-a583-c14ac2cca6e8', '9888e8dc-be24-5859-b614-5e4d06b43847', 1, 'An ideal conductor with zero resistance has zero voltage drop across it, regardless of the current flowing through it.', 'APPROVED'),
  ('a04180cb-66f5-5f79-9113-45343cd1df54', '90d0f439-1559-552a-b67a-415958be5dcc', 1, 'An open circuit can be modelled as having infinite resistance, since no current can flow through it regardless of the applied voltage.', 'APPROVED'),
  ('037ef26e-72dc-50fd-8550-2a6d3c71c77b', '6fc71fb7-0bb6-532c-89ad-9e3d0ba9749d', 1, 'A resistor is a component manufactured to provide a specific, stable value of resistance, used in circuits to limit current or to divide voltage.', 'APPROVED'),
  ('0edcba7b-873c-5260-9368-78ff42db6fed', '01fa5403-a042-5122-a105-530cc34090ad', 1, 'A capacitor is a component that stores electrical charge and energy by separating charge in an electric field between two conductive plates; a charged capacitor stores this energy in the electric field between its plates.', 'APPROVED'),
  ('2196849f-4935-562d-a9ca-40219fd99557', '6540f20f-de43-5db2-9329-e8257a41924b', 1, 'A capacitor opposes a sudden change in the voltage across it: connected in a circuit with resistance, it charges and discharges exponentially over time (governed by the time constant tau = R times C) rather than the voltage across it changing instantaneously.', 'APPROVED'),
  ('fb4e2b08-eead-5fb9-8fb4-2e7bc7882c05', '33a2bc1a-28e0-5661-955b-232811114c8b', 1, 'A rectifier circuit uses one or more diodes to convert an alternating-current supply into a direct-current (or pulsating direct-current) output.', 'APPROVED'),
  ('02dc74ec-6b1a-55f3-b62a-028b0a4c8c7d', '07c95449-1bad-51c8-89f8-ec7bd2956183', 1, 'A half-wave rectifier uses a single diode to allow only one half-cycle of an AC waveform through to the load, blocking the other half-cycle, producing a pulsating DC output.', 'APPROVED'),
  ('4f61fa45-294b-50dc-be68-d5f8bcdad051', 'cc5d56f5-98f7-528a-926a-3754b54128ba', 1, 'A full-wave bridge rectifier uses four diodes arranged so that both half-cycles of an AC waveform are converted to the same output polarity, producing a pulsating DC output with less ripple than a half-wave rectifier.', 'APPROVED'),
  ('9feb6f56-b6ef-5c68-925e-361c22c0a749', 'ef382a51-d3ea-5d19-a46f-17343e3e643a', 1, 'A diode is a semiconductor device formed at a p-n junction that conducts current easily in one direction (forward bias, junction narrows) and blocks current in the other direction (reverse bias, junction widens).', 'APPROVED'),
  ('fd29de09-e502-51b9-878d-eb740476ef23', 'eb45f4e0-259f-5d47-bb28-c8bc8a53ae9e', 1, 'A Zener diode is a special-purpose diode designed to be operated in reverse breakdown at a well-defined breakdown voltage without damage, so it maintains a substantially constant voltage across itself and can be used to regulate voltage.', 'APPROVED'),
  ('7e2d5960-93fc-5264-8e74-b15f2c873a22', '7f85628c-dc99-57f4-b1c4-d3b9ab96a003', 1, 'A light-emitting diode (LED) produces light by electroluminescence: when forward-biased, recombination of electrons and holes at the junction releases energy as photons.', 'APPROVED'),
  ('a424633e-3137-55e6-83f4-71f5e71488c2', '1996ab99-664d-5f5e-bb0b-b0b3a63b1655', 1, 'A photodiode is a diode optimised to generate a photocurrent in response to incident light falling on its junction, allowing it to detect or measure light.', 'APPROVED'),
  ('9c02a68e-97ea-56bb-88c3-cfb6e598868b', 'a6483967-4a5e-5054-a40e-2eeb0006a2c6', 1, 'An NTC (negative-temperature-coefficient) thermistor''s electrical resistance decreases as its temperature increases, allowing it to be used as a temperature-sensing component.', 'APPROVED'),
  ('7d20a649-e150-55ec-be94-6f580f4bc201', '4d2568d1-c552-5799-a23f-22f1f22fea5e', 1, 'A PTC (positive-temperature-coefficient) thermistor''s electrical resistance increases as its temperature increases, in contrast to an NTC thermistor''s resistance, which decreases as temperature increases.', 'APPROVED'),
  ('d6c155f6-27d6-57cf-a09c-5a5da0633a75', '058a8d7a-81b0-5df7-bd0d-a8d6072f3db6', 1, 'A DIAC is a bidirectional thyristor that remains a high-impedance, non-conducting device until the voltage across it exceeds its breakover voltage, at which point it switches into conduction in either direction; it is almost never used alone, but to trigger other thyristor devices.', 'APPROVED'),
  ('15a84642-ed55-53c8-880b-936337e9be98', '323e1b6c-1afc-5f50-bf6f-41c8c41fde98', 1, 'A silicon-controlled rectifier (SCR) conducts current in one direction only once a sufficient gate current triggers it into conduction, and continues conducting until the current through it falls below the device''s holding current.', 'APPROVED'),
  ('af71ccf6-6475-512b-8484-ae8013bdd343', '9a86e758-d186-5746-85ab-e130855cc59c', 1, 'A TRIAC acts much like two silicon-controlled rectifiers connected back-to-back, allowing it to conduct current in both directions once triggered by gate current, making it suitable for controlling alternating current.', 'APPROVED'),
  ('a283c57e-1e25-57dc-96a4-fdb2b6d9e0f6', 'fdfbba47-f146-522a-b771-3d6c25f8785c', 1, 'A bipolar junction transistor is a three-terminal semiconductor device whose collector-emitter current is controlled by a much smaller base current, allowing it to act as an electrically controlled switch (fully off with no base current, fully on/saturated with sufficient base current) or as an amplifier.', 'APPROVED'),
  ('eb9c3f1f-9a04-55df-a175-802f2090cc85', 'd9a9ec04-f1c5-5dfc-b854-2a1e78fb16ca', 1, 'An inverter converts a direct-current supply into an alternating-current output, by using electronic switching circuits to switch the DC input in a controlled sequence and generate the AC voltage or current waveform.', 'APPROVED'),
  ('b076d434-14e1-5886-865e-8b623eaccc7c', 'fc5e29c9-dc15-567c-8ad0-68f68b463608', 1, 'A household dimmer switch typically uses a TRIAC to control the average power delivered to a lamp, by switching on at a controlled phase angle within each AC half-cycle.', 'APPROVED'),
  ('39ae11f1-1769-539e-a7cc-1e98cdd9c7d8', '4467eece-5cb0-5c62-bbdc-ff2e8e8b546e', 1, 'Silicon-controlled rectifiers are commonly used in motor-control circuits to control the electrical power delivered to a motor.', 'APPROVED'),
  ('62b86852-7b88-5181-9476-bd2cc51d3db8', 'b8657ad5-ab8c-571a-b7e6-d012ddb71c16', 1, 'Thermistors are used for temperature sensing in heating and ventilation systems, including central-heating and boiler controls, providing a feedback signal a control circuit (such as a thermostat) uses to switch a heating load on or off at set temperatures.', 'APPROVED'),
  ('1d4521fe-3c5f-5618-a80f-8b6610cd5baf', '4fbab585-31b6-5aeb-a2aa-208da87ee3b9', 1, 'An infrared LED transmitter and a photoelectric (photodiode) receiver can be paired as a beam-break sensor: an object interrupting the beam changes the receiver''s output, which triggers a relay output wired to an alarm control panel -- the basis of commercially manufactured security/intrusion-detection beam sensors.', 'APPROVED'),
  ('1cffe5fb-3339-5b6b-ad7e-3cadbf29be51', '29d1b9cd-af07-5761-a3e5-d7407fcee72f', 1, 'A simple electronic security-alarm circuit uses a transistor to detect a break in a normally-closed sensor loop; the transistor then triggers a thyristor, which latches on and continues to power a sounder even if the loop is reclosed, until the circuit is deliberately reset.', 'APPROVED'),
  ('68824f29-1a62-5b8c-a2f5-271627354af7', '596b4654-19c9-5fb1-9e22-b9021577cf3b', 1, 'Telephone equipment includes a diode bridge connected across the two wires of the telephone line, so that the equipment''s internal circuitry is unaffected by which way round the line is connected.', 'APPROVED'),
  ('e7b8ad5d-c678-5049-93d3-a0bd2e4cb459', '24df4850-a17e-53be-934f-9a4d9c368881', 1, 'The traditional UK master telephone socket arrangement contains a capacitor that couples the AC ringing signal to the line while blocking the line''s DC, and a resistor that provides a defined test load for line testing when no telephone is connected; older master sockets also included a surge protector to suppress transient overvoltages on the line. Secondary (extension) sockets, wired in parallel from the master socket, contain none of these components.', 'APPROVED'),
  ('4668082c-2885-5f53-ae06-240c3aaf6cae', '827c5fb8-98ac-550f-875d-27b19da1c8d8', 1, 'A wireless control system uses an electronic receiver and decoder circuit that responds to a transmitted control signal by switching an output to operate a device.', 'APPROVED')
insert into public.assertion_provenance_links (id, assertion_version_id, source_locator_id, provenance_role)
values
  ('803ffcf9-c7d8-5c1a-949e-ae6fdce5323e', 'f78d2be9-1018-5162-9667-10cc67e9a1c8', '24c8d5ea-6742-5af0-b8fb-ce45bf1f6eea', 'DEFINES'),
  ('42ad3119-d540-562f-b0ee-82ac22a0c39e', '1ba986a4-9988-5e91-9895-9254b37f6d00', '24c8d5ea-6742-5af0-b8fb-ce45bf1f6eea', 'DEFINES'),
