insert into public.misconceptions (id, identifier, description)
values
  ('7d60aa49-c86f-5f14-b315-eb034169b1b9', 'MIS-EL-OHM-UNRELATED-SYMBOLS-001', 'Treats V, I and R as three unrelated symbols to memorise rather than as a single relationship connecting voltage, current and resistance (V = I times R).'),
  ('56e101e4-fb3f-5ac7-b051-e5552da71925', 'MIS-EL-OHM-REARRANGE-ERROR-001', 'Incorrectly rearranges a multiplicative relationship such as V = I times R or P = V times I (for example moving a variable to the wrong side, or inverting the wrong pair of variables) when isolating a different subject.'),
  ('239d57f1-2fb0-529d-8fbd-aa88569408f8', 'MIS-EL-OHM-WRONG-OPERATION-001', 'Selects the wrong arithmetic operation when calculating an unknown quantity from V = I times R (for example multiplying instead of dividing when solving for current or resistance, or dividing the two known quantities in the wrong order).'),
  ('1f70096c-498f-501b-8f4f-32c2ba6a2ea7', 'MIS-EL-UNIT-CONFUSION-001', 'Confuses the electrical quantities voltage, current, resistance, power and energy with their SI units (volt, ampere, ohm, watt, joule), or attaches the wrong unit to the wrong quantity.'),
  ('c4f4f3b4-3d6b-5b1d-81c8-f858d5990497', 'MIS-EL-SI-PREFIX-ERROR-001', 'Confuses SI-prefix magnitudes when converting between units (for example treating milliamps and amps as numerically equal, or converting in the wrong direction, such as multiplying instead of dividing by the scale factor).'),
  ('2139d586-4651-593e-a4ae-db22d5d46b81', 'MIS-EL-SERIES-PARALLEL-CONFUSION-001', 'Confuses series and parallel circuit structure, for example treating components wired in parallel as if they were in series (or vice versa) when identifying current and voltage relationships.'),
  ('922c9d35-b181-592b-97a6-c68b4583dbf5', 'MIS-EL-PARALLEL-RESISTANCE-ADDITION-001', 'Calculates the total resistance of a parallel circuit by simply adding the branch resistances, as if they were in series, instead of using the reciprocal-of-sum-of-reciprocals relationship.'),
  ('a5dcf48e-feee-5bff-b2e2-98ac1fb8761a', 'MIS-EL-RECIPROCAL-FORGOTTEN-INVERT-001', 'Correctly sums the reciprocals of the branch resistances in a parallel circuit but forgets to take the reciprocal of the result, giving an answer that is the reciprocal of the correct total resistance rather than the total resistance itself.'),
  ('1748a203-345e-520d-95a4-5596f2e39812', 'MIS-EL-POWER-ENERGY-CONFUSION-001', 'Confuses power and energy, treating the two quantities (and their units, the watt and the joule) as interchangeable.'),
  ('e0cad2b0-590a-5742-95dd-22cf12b09a03', 'MIS-EL-VOLTAGE-DROP-MISUNDERSTANDING-001', 'Believes that voltage is ''used up'' or disappears as current flows through a series circuit, rather than understanding voltage drop as the potential difference resulting from current flowing through resistance.'),
  ('6baca2c4-2afa-50d0-8c24-c3a6c8cd5a65', 'MIS-EL-CONDUCTOR-INSULATOR-CONFUSION-001', 'Confuses which materials are good conductors versus insulators, or believes conductivity and resistance are unrelated properties.'),
  ('7e6c7cdc-43c7-5e7e-95d9-f549d06a41dc', 'MIS-FM-PROPORTION-DIRECTION-CONFUSION-001', 'Confuses direct and inverse proportion, for example assuming a quantity increases when it should decrease as another quantity increases.'),
  ('ae13cd8b-656d-58f5-b9cc-c3185b818096', 'MIS-EL-CURRENT-VOLTAGE-CONFUSION-001', 'Confuses current and voltage as concepts, for example treating current as something a source ''has'' independent of the circuit rather than voltage driving current through resistance.'),
  ('09c6bf8a-74b3-50fa-8d9d-e9fed3180996', 'MIS-EL-RESISTANCE-RESISTIVITY-CONFUSION-001', 'Treats resistance and resistivity as the same property, not realising that resistivity is a material property independent of a conductor''s dimensions while resistance also depends on length and cross-sectional area.'),
  ('2f3573e1-8586-5044-aeee-f694f9bd255b', 'MIS-EL-INSTRUMENT-CONNECTION-CONFUSION-001', 'Connects a voltmeter in series or an ammeter in parallel, swapping the correct connection method for the two instruments.'),
  ('ceee04f0-5754-55dc-9c4f-320c7a308bd6', 'MIS-EL-ELECTRON-CURRENT-DIRECTION-CONFUSION-001', 'Confuses conventional current direction (positive to negative) with the actual direction of electron flow (negative to positive) in a conductor.'),
  ('ade75842-2833-579c-b773-5529aedc65e6', 'MIS-EL-AC-DC-CONFUSION-001', 'Treats alternating current and direct current as the same, or believes an AC supply has a single constant unchanging value like a DC supply.'),
  ('32b2bde1-f82a-5488-89d7-3a2f55a98005', 'MIS-EL-PEAK-RMS-CONFUSION-001', 'Confuses the peak value of an AC waveform with its RMS value, for example assuming a stated AC supply voltage (such as 230 V) is a peak value rather than an RMS value.'),
  ('1701d6b6-fe48-569f-ac1a-7aae197bcc67', 'MIS-EL-EMF-VOLTAGE-CONFUSION-001', 'Confuses EMF (the source''s own electrical energy per unit charge) with terminal voltage, treating them as always identical rather than recognising terminal voltage is reduced by the source''s internal resistance when supplying current.'),
  ('b1a8f3d9-aa26-5d7b-91ad-e81c50e4f945', 'MIS-EL-ENERGY-UNIT-CONFUSION-001', 'Confuses the joule and the kilowatt-hour as interchangeable without converting between them, or is unaware that they measure the same quantity (energy) at different scales.'),
  ('1b529a20-6701-51f0-b88b-b5d234110c26', 'MIS-EL-DIODE-DIRECTION-CONFUSION-001', 'Confuses which direction a diode allows current to flow (forward bias) versus blocks it (reverse bias), or assumes a diode conducts equally in both directions like a plain resistor.')
